// Links the static dav1d library in the folder SNOWLARK_DAV1D_DIR names (tools/dav1d/build.ps1 makes it;
// dev.ps1 sets the variable). Without it the crate defines the few dav1d functions CrabbyAvif calls itself, each
// failing, so the build links and AVIF images go to the other decoder. The bindings are checked in
// (src/bindings.rs, generated by tools/dav1d/build.ps1 -Bindings), so no build needs libclang.

use std::path::PathBuf;

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-env-changed=SNOWLARK_DAV1D_DIR");
    let dir = std::env::var_os("SNOWLARK_DAV1D_DIR").map(PathBuf::from);
    // (the library for the target being built: MSVC's name on Windows, the archive's elsewhere)
    let file = match std::env::var("CARGO_CFG_TARGET_ENV").as_deref() {
        Ok("msvc") => "dav1d.lib",
        _ => "libdav1d.a",
    };
    let lib = dir.as_ref().map(|d| d.join(file));
    match (&dir, &lib) {
        (Some(dir), Some(lib)) if lib.is_file() => {
            println!("cargo:rerun-if-changed={}", lib.display());
            println!("cargo:rustc-link-search=native={}", dir.display());
            println!("cargo:rustc-link-lib=static=dav1d");
        }
        _ => {
            println!("cargo:rustc-cfg=dav1d_missing");
            println!(
                "cargo:warning=no dav1d library (SNOWLARK_DAV1D_DIR, made by tools/dav1d/build.ps1): AVIF images are decoded without it"
            );
        }
    }
}
